"""The tp4/ship-4 window pack (scripts/ci/references/fusion-jobs/ship4, generated by make_ship4_jobs.py).

ORDER.txt lists exactly the folder's templates, each once, on the one image, with a total that matches its header; B0 bakes the production profile with the K64j-OQ graft; every NEEDS line names earlier
jobs; the ARC-ZERO range starts at the audited attach and ends at the last card job before the ship build; every job runs the profile its name says (the audited twin for the attach and the tier plans, the
approved fusion ship profile for every control, the candidate for every arm, the no-grid twin for the grid pair); every template parses through the job reader with rc 0, except the ship build, which is
refused exactly while the decision is PENDING; the gate rows are make_fusion_jobs.ship_rows."""

import json
from pathlib import Path
import re
import subprocess
import sys
import unittest

HERE = Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))

import c2_serving_job as job  # noqa: E402
import make_fusion_jobs as fusion_jobs  # noqa: E402
import make_fusion_profiles as fusion  # noqa: E402
import make_ship4_jobs as pack  # noqa: E402
import make_ship4_profiles as twins  # noqa: E402
import serving_c2_contract as contract  # noqa: E402

PACK = pack.FOLDER
READER = HERE / 'c2_serving_job.py'
PROFILES = json.loads((HERE / 'qwen_c2_profiles.json').read_text(encoding='utf-8'))['profiles']
IMAGE = 'tp4-ship-4'
SHIP, AUDIT, NOGRID13, CONTROL = pack.SHIP, pack.AUDIT, pack.NOGRID13, pack.CONTROL

# job -> (mode, profile, smoke tests, telemetry)
EXPECTED = {
    'B0-build-window': ('stop', 'c2-packed-tp4', '', ''),
    'X0-status-rescan-reset': ('stop', '', '', ''),
    'A1-s4-audited-attach': ('stop', AUDIT, pack.AUDIT_TESTS, '1'),
    'GX0-exact-control': ('stop', CONTROL, fusion_jobs.GX_TESTS, '1'),
    'GX1-exact-ship': ('stop', SHIP, fusion_jobs.GX_TESTS, '1'),
    'G1-ship-gate': ('stop', SHIP, fusion_jobs.G1_TESTS, '1'),
    'TC1-tier-concurrent-audited': ('stop', '', '', ''),
    'C1-control-a': ('soft', CONTROL, pack.TIMED_TESTS, '1'),
    'L1-s4-a': ('soft', SHIP, pack.TIMED_TESTS, '1'),
    'C2-control-b': ('soft', CONTROL, pack.TIMED_TESTS, '1'),
    'L2-s4-b': ('soft', SHIP, pack.TIMED_TESTS, '1'),
    'TC2-tier-concurrent-control-timed': ('soft', '', '', ''),
    'TC3-tier-concurrent-s4-timed': ('soft', '', '', ''),
    'TC4-tier-concurrent-control-repeat': ('soft', '', '', ''),
    'TC5-tier-concurrent-s4-repeat': ('soft', '', '', ''),
    'N1-s4-nogrid13-a': ('soft', NOGRID13, pack.GRID_TESTS, '1'),
    'N2-s4-nogrid13-b': ('soft', NOGRID13, pack.GRID_TESTS, '1'),
    'G2-prefix-hit': ('soft', '', '', ''),
    'TQ1-tier-quota-isolation': ('soft', '', '', ''),
    'Z-reset': ('soft', '', '', ''),
    'B1-ship-build': ('soft', '', '', ''),
    'SR-platform-replay': ('soft', '', '', ''),
}
PREFIX_JOBS = {'TC1-tier-concurrent-audited': ('tier-concurrent', AUDIT), 'TC2-tier-concurrent-control-timed': ('tier-concurrent-timed', CONTROL),
               'TC3-tier-concurrent-s4-timed': ('tier-concurrent-timed', SHIP), 'TC4-tier-concurrent-control-repeat': ('tier-concurrent-timed', CONTROL),
               'TC5-tier-concurrent-s4-repeat': ('tier-concurrent-timed', SHIP), 'TQ1-tier-quota-isolation': ('tier-quota', AUDIT), 'G2-prefix-hit': ('levern-hit', SHIP)}


def order_lines():
    return [line.split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.strip() and not line.startswith('#')]


def directives(prefix):
    return [line[len(prefix):].split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.startswith(prefix)]


def resolve(token, names):
    return [name for name in names if name == token or name.startswith(token + '-')]


def values(name):
    return job.parse_env((PACK / (name + '.env')).read_text(encoding='utf-8'))


def run_reader(path):
    result = subprocess.run([sys.executable, '-B', '-s', str(READER), str(path), str(HERE / 'qwen_c2_profiles.json')], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=str(HERE.parent.parent))
    return result.returncode, (result.stdout + result.stderr).decode('utf-8', 'replace')


class GeneratorTests(unittest.TestCase):
    def test_the_checked_in_pack_is_what_the_generator_makes(self):
        wanted = pack.generate()
        found = {path.name: path.read_text(encoding='utf-8') for path in PACK.glob('*') if path.is_file()}
        self.assertEqual(sorted(found), sorted(wanted))
        for name in wanted:
            self.assertEqual(found[name], wanted[name], name)

    def test_the_generator_check_exits_zero(self):
        result = subprocess.run([sys.executable, '-B', '-s', str(HERE / 'make_ship4_jobs.py'), '--check'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=str(HERE.parent.parent))
        self.assertEqual(result.returncode, 0, result.stderr.decode('utf-8', 'replace'))

    def test_the_fusion_pack_generator_leaves_the_folder_alone_and_lists_it(self):
        text = (HERE / 'references' / 'fusion-jobs' / 'ORDER.txt').read_text(encoding='utf-8')
        self.assertIn('fusion-jobs/ship4', text)
        self.assertIn('references/fusion-jobs/ship4: the gates, the audited attach and the timed windows', text)
        result = subprocess.run([sys.executable, '-B', '-s', str(HERE / 'make_fusion_jobs.py'), '--check'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=str(HERE.parent.parent))
        self.assertEqual(result.returncode, 0, result.stderr.decode('utf-8', 'replace'))


class OrderTests(unittest.TestCase):
    def test_the_order_lists_exactly_the_folders_templates_each_once_on_the_one_image(self):
        lines = order_lines()
        names = [line[0] for line in lines]
        self.assertEqual(sorted(names), sorted(path.stem for path in PACK.glob('*.env')))
        self.assertEqual(names, list(EXPECTED), 'the order of the window: value first')
        for name, mode, image, minutes in lines:
            self.assertEqual((mode, image, int(minutes) > 0), (EXPECTED[name][0], IMAGE, True), name)

    def test_the_total_in_the_header_is_the_sum_of_the_lines(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        total = sum(int(line[3]) for line in order_lines())
        found = re.search(r'SR 30: (\d+) minutes \((\d+) h (\d+) min\) in all, (\d+) minutes of cards before the ship build \(X0 to Z\); the gates block \(B0 to TC1\) is (\d+) minutes', text)
        self.assertIsNotNone(found)
        minutes = {line[0].split('-')[0]: int(line[3]) for line in order_lines()}
        cards = total - minutes['B0'] - minutes['B1'] - minutes['SR']
        gates = sum(minutes[token] for token in 'B0 X0 A1 GX0 GX1 G1 TC1'.split())
        self.assertEqual((int(found.group(1)), int(found.group(2)) * 60 + int(found.group(3)), int(found.group(4)), int(found.group(5))), (total, total, cards, gates))

    def test_the_stop_jobs_are_the_build_the_status_and_the_gates(self):
        self.assertEqual([line[0] for line in order_lines() if line[1] == 'stop'],
                         ['B0-build-window', 'X0-status-rescan-reset', 'A1-s4-audited-attach', 'GX0-exact-control', 'GX1-exact-ship', 'G1-ship-gate', 'TC1-tier-concurrent-audited'])

    def test_every_needs_line_names_earlier_jobs_and_every_job_but_b0_and_z_waits_for_something(self):
        names = [line[0] for line in order_lines()]
        waiting = set()
        for tokens in directives('# NEEDS '):
            arrow = tokens.index('<-')
            left, right = tokens[:arrow], tokens[arrow + 1:]
            self.assertTrue(left and right, tokens)
            for token in left + right:
                self.assertEqual(len(resolve(token, names)), 1, token)
            first = min(names.index(resolve(token, names)[0]) for token in left)
            for token in right:
                self.assertLess(names.index(resolve(token, names)[0]), first, '%s must run before %s' % (token, left))
            waiting |= set(resolve(token, names)[0] for token in left)
        self.assertEqual(sorted(waiting), sorted(name for name in names if name not in ('B0-build-window', 'Z-reset')))

    def test_the_dependencies_say_what_the_read_rules_say(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        for line in ('X0 <- B0', 'A1 <- X0', 'GX0 <- A1', 'GX1 <- GX0', 'G1 <- GX1', 'TC1 <- G1', 'C1 <- TC1', 'L1 <- C1', 'C2 <- L1', 'L2 <- C2', 'TC2 <- G1', 'TC3 <- TC1 TC2', 'TC4 <- TC3', 'TC5 <- TC4',
                     'N1 <- L1', 'N2 <- L2 N1', 'G2 <- G1', 'TQ1 <- TC1', 'B1 <- G1 GX1', 'SR <- B1 G1 GX1'):
            self.assertIn('# NEEDS %s\n' % line, text)

    def test_the_arc_range_runs_from_the_audited_attach_to_the_last_card_job_before_the_ship_build(self):
        ranges = directives('# ARC-ZERO ')
        self.assertEqual(ranges, [['A1', 'TQ1']])
        names = [line[0] for line in order_lines()]
        first, last = (resolve(token, names)[0] for token in ranges[0])
        self.assertEqual(names[names.index(last) + 1], 'Z-reset')
        self.assertEqual(names[names.index(first) - 1], 'X0-status-rescan-reset')
        self.assertEqual(names[names.index('Z-reset') + 1:], ['B1-ship-build', 'SR-platform-replay'])

    def test_the_order_says_what_the_candidate_is_and_how_it_is_decided(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        waiver = PROFILES[SHIP][contract.TRAFFIC_WAIVER]
        for phrase in (SHIP, waiver['id'], '--approve-ship', '--ship traffic-s4', 'QWEN_FAST_GRID13', 'NOTHING IN THE CANDIDATE HAS RUN ON A CARD TOGETHER', 'octo3_report.py', 'octo_compare.py', 'octo_judge',
                       'tier_concurrent_compare.py', 'parked_compare.py', 'PENDING', 'ARC PAUSE'):
            self.assertIn(phrase, text)


class JobTests(unittest.TestCase):
    def test_every_template_parses_with_rc_zero_except_the_ship_build_while_the_decision_is_pending(self):
        pending = PROFILES[SHIP][contract.TRAFFIC_WAIVER]['decision'].startswith('PENDING')
        for path in sorted(PACK.glob('*.env')):
            with self.subTest(path.name):
                code, text = run_reader(path)
                if path.stem == 'B1-ship-build' and pending:
                    self.assertNotEqual(code, 0, text)
                    self.assertIn('not APPROVED', text)
                else:
                    self.assertEqual(code, 0, text)
                    self.assertNotIn('refused', text)

    def test_every_job_runs_the_profile_tests_and_image_its_row_says(self):
        for name, (mode, profile, tests, telemetry) in EXPECTED.items():
            if name == 'B1-ship-build':
                continue
            with self.subTest(name):
                got = values(name)
                self.assertEqual(got.get('C2_IMAGE_TAG'), IMAGE)
                self.assertEqual(got.get('C2_CARDS'), 'quad')
                if profile:
                    self.assertEqual(got.get('C2_PROFILE'), profile)
                    self.assertIn(profile, PROFILES)
                self.assertEqual(got.get('C2_SMOKE_TESTS', ''), tests)
                self.assertEqual(got.get('C2_TELEMETRY', ''), telemetry)

    def test_the_prefix_jobs_run_the_plan_and_profile_the_row_says_and_the_controls_are_the_approved_fusion_ship(self):
        for name, (plan, profile) in PREFIX_JOBS.items():
            with self.subTest(name):
                got = values(name)
                self.assertEqual((got['C2_PREFIX_PLAN'], got['C2_PREFIX_PROFILE'], got['C2_PREFIX_BASELINE']), (plan, profile, 'none'))
                self.assertIn(got['C2_PREFIX_PROFILE'], PROFILES)
        self.assertEqual(PROFILES[CONTROL][contract.TRAFFIC_WAIVER]['id'], 'w2-er-fx-262k-2026-10-11')
        self.assertTrue(PROFILES[CONTROL][contract.TRAFFIC_WAIVER]['decision'].startswith('APPROVED'))

    def test_b0_bakes_the_production_profile_with_the_oneq_graft_and_nothing_else(self):
        got = values('B0-build-window')
        self.assertEqual((got['C2_ACTIONS'], got['C2_BAKE_DEFAULT_PROFILE'], got['C2_BAKE_GRAFT']), ('build', fusion.PARENT, 'K64j-OQ'))

    def test_b1_is_the_ships_own_build_row_renamed(self):
        got = values('B1-ship-build')
        self.assertEqual((got['C2_ACTIONS'], got['C2_BAKE_DEFAULT_PROFILE'], got['C2_BAKE_GRAFT']), ('build', SHIP, 'K64j-OQ'))
        self.assertIn('B1 (AFTER THE OWNER APPROVES', (PACK / 'B1-ship-build.env').read_text(encoding='utf-8'))
        self.assertEqual(values('SR-platform-replay')['C2_REPLAY_PROFILE'], SHIP)

    def test_the_gate_rows_are_the_single_candidate_packs_rows(self):
        plan = fusion.normalise(fusion.read_manifests())
        rows = {row['name']: row for row in fusion_jobs.ship_rows(plan, fusion_jobs.shipped_spec(plan, pack.spec(plan)))}
        for name in ('G1-ship-gate', 'GX0-exact-control', 'GX1-exact-ship', 'G2-prefix-hit', 'SR-platform-replay'):
            text = (PACK / (name + '.env')).read_text(encoding='utf-8').replace('\n# ', ' ')
            for phrase in rows[name]['extra']:
                self.assertIn(phrase, text.splitlines() if phrase.startswith('C2_') else text)
        self.assertEqual(values('GX0-exact-control')['C2_PROFILE'], CONTROL)
        for name in ('G1-ship-gate', 'GX1-exact-ship'):
            text = (PACK / (name + '.env')).read_text(encoding='utf-8').replace('\n# ', ' ')
            for phrase in ('OCTO READ', 'TIER READ', 'owner traffic waiver <id>', 'UNQUALIFIED', 'octo 8-row served path'):
                self.assertIn(phrase, text, name)

    def test_the_candidate_arms_are_the_control_plus_the_candidates_env_and_the_grid_pair_differs_by_one_line(self):
        control, ship, nogrid = PROFILES[CONTROL]['env'], PROFILES[SHIP]['env'], PROFILES[NOGRID13]['env']
        self.assertEqual(sorted(set(control) - set(ship)), [])
        self.assertEqual({key for key in ship if nogrid.get(key) != ship[key]}, {'QWEN_FAST_GRID13', contract.OCTO_WAIVER_ENV})
        for name in ('C1-control-a', 'C2-control-b'):
            self.assertEqual(values(name)['C2_PROFILE'], CONTROL)
        for name in ('L1-s4-a', 'L2-s4-b'):
            self.assertEqual(values(name)['C2_PROFILE'], SHIP)
        for name in ('N1-s4-nogrid13-a', 'N2-s4-nogrid13-b'):
            self.assertEqual(values(name)['C2_PROFILE'], NOGRID13)

    def test_the_four_decode_jobs_run_the_same_tests_and_the_deep_ones_exist_in_the_client(self):
        tests = {values(name)['C2_SMOKE_TESTS'] for name in ('C1-control-a', 'L1-s4-a', 'C2-control-b', 'L2-s4-b')}
        self.assertEqual(tests, {pack.TIMED_TESTS})
        smoke = (HERE / 'c2_serving_smoke.py').read_text(encoding='utf-8')
        for name in set(pack.TIMED_TESTS.split(',')) | set(pack.GRID_TESTS.split(',')) | set(pack.AUDIT_TESTS.split(',')):
            self.assertIn(name, smoke)
        self.assertTrue(set(pack.GRID_TESTS.split(',')) <= set(pack.TIMED_TESTS.split(',')))

    def test_the_tier_jobs_say_what_the_control_is_and_is_not(self):
        text = (PACK / 'TC3-tier-concurrent-s4-timed.env').read_text(encoding='utf-8').replace('\n# ', ' ')
        for phrase in ('APPROVED FUSION SHIP PROFILE', 'no tier, no octo', 'tier_concurrent_compare.py', 'NOT_EXERCISED', 'shape=octo'):
            self.assertIn(phrase, text)
        self.assertIn('the tier pack', text)
        tq = (PACK / 'TQ1-tier-quota-isolation.env').read_text(encoding='utf-8').replace('\n# ', ' ')
        self.assertIn('THE QUOTAS ARE NOT IN THE CANDIDATE', tq)

    def test_nothing_in_the_pack_names_a_host_an_address_a_digest_or_a_path(self):
        for path in list(PACK.glob('*')):
            text = path.read_text(encoding='utf-8')
            for word in ('thatch' + '.local', '192' + '.168.', 'sha256' + ':', '/' + 'home' + '/'):
                self.assertNotIn(word, text, path.name)


if __name__ == '__main__':
    unittest.main()
